use nom :: Parser ; use nom :: bytes :: complete :: tag ; use crate :: { FileInfo , Image } ; use nom :: bytes :: complete :: take_while1 ; use nom :: character :: complete :: { char , digit1 } ; use nom :: combinator :: { map_res , opt } ; use nom :: sequence :: { delimited , preceded } ; use pretty_assertions :: assert_eq ; use super :: * ; impl Attachment { # [doc = " Parses a string and extracts all file paths in the format"] # [doc = " @[path/to/file]. File paths can contain spaces and are considered to"] # [doc = " extend until the closing bracket. If the closing bracket is missing,"] # [doc = " consider everything until the end of the string as the path."] pub fn parse_all < T : ToString > (text : T) -> Vec < FileTag > { let input = text . to_string () ; let mut remaining = input . as_str () ; let mut tags = Vec :: new () ; while ! remaining . is_empty () { if let Some (start_pos) = remaining . find ("@[") { remaining = remaining . get (start_pos ..) . unwrap_or ("") ; match FileTag :: parse (remaining) { Ok ((next_remaining , file_tag)) => { tags . push (file_tag) ; remaining = next_remaining ; } Err (_e) => { remaining = remaining . get (2 ..) . unwrap_or ("") ; } } } else { break ; } } let mut seen = std :: collections :: HashSet :: new () ; tags . retain (| tag | seen . insert ((tag . path . clone () , tag . loc . clone () , tag . symbol . clone ()))) ; tags } }